<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, Building2, ClipboardList, CreditCard, LogOut, Menu, ShieldAlert, Users } from 'lucide-vue-next'
import { supabase } from './lib/supabase'

type Overview = { tenants: number; users: number; pools: number; open_pools: number; matches: number; results: number; audit_events_24h: number; pending_plan_requests: number }
type Tenant = { tenant_id: string; name: string; plan_code: string; pools: number; participants: number; created_at: string }
type Request = { id: string; tenant_name: string; offer_code: string; status: string; requested_at: string }
type Offer = { offer_code: string; plan_code: string; scope: string; price_minor: number; currency: string; billing_period: 'month' | 'year' | 'one_time'; benefits: string[]; is_public: boolean }
const menu = [{ key: 'overview', label: 'Resumen', icon: Activity }, { key: 'tenants', label: 'Organizaciones', icon: Building2 }, { key: 'requests', label: 'Solicitudes', icon: ClipboardList }, { key: 'plans', label: 'Precios', icon: CreditCard }]
const active = ref('overview'), mobileOpen = ref(false), loading = ref(true), denied = ref(false), signedIn = ref(false), email = ref(''), password = ref(''), message = ref('')
const overview = ref<Overview | null>(null), tenants = ref<Tenant[]>([]), requests = ref<Request[]>([]), offers = ref<Offer[]>([]), saving = ref('')
const cards = computed(() => overview.value ? [{ label: 'Organizaciones', value: overview.value.tenants }, { label: 'Usuarios', value: overview.value.users }, { label: 'Quinielas abiertas', value: overview.value.open_pools }, { label: 'Resultados', value: overview.value.results }, { label: 'Eventos 24 h', value: overview.value.audit_events_24h }, { label: 'Solicitudes', value: overview.value.pending_plan_requests }] : [])
async function load(): Promise<void> {
  loading.value = true; message.value = ''
  const db = supabase(); const { data: ok } = await db.rpc('is_platform_admin')
  if (!ok) { denied.value = true; loading.value = false; return }
  const [summary, tenantList, requestList, offerList] = await Promise.all([db.rpc('platform_console_overview'), db.rpc('platform_console_tenants', { p_query: null }), db.rpc('platform_console_plan_requests'), db.rpc('platform_console_offers')])
  if (summary.error || tenantList.error || requestList.error || offerList.error) message.value = 'No fue posible cargar una parte de la consola. Inténtalo de nuevo.'
  overview.value = (summary.data ?? null) as Overview | null; tenants.value = (tenantList.data ?? []) as Tenant[]; requests.value = (requestList.data ?? []) as Request[]; offers.value = (offerList.data ?? []) as Offer[]; loading.value = false
}
async function saveOffer(offer: Offer): Promise<void> { saving.value = offer.offer_code; const { error } = await supabase().rpc('update_plan_offer', { p_offer_code: offer.offer_code, p_price_minor: offer.price_minor, p_currency: offer.currency, p_billing_period: offer.billing_period, p_benefits: offer.benefits, p_is_public: offer.is_public }); saving.value = ''; message.value = error ? 'No se pudo actualizar la oferta.' : 'Oferta actualizada y auditada.' }
async function signOut(): Promise<void> { await supabase().auth.signOut(); window.location.reload() }
async function signIn(): Promise<void> { message.value = ''; const { error } = await supabase().auth.signInWithPassword({ email: email.value.trim(), password: password.value }); if (error) { message.value = 'No pudimos iniciar sesión.'; return } signedIn.value = true; await load() }
onMounted(async () => { const { data } = await supabase().auth.getSession(); signedIn.value = Boolean(data.session); if (signedIn.value) await load(); else loading.value = false })
</script>

<template><section v-if="!signedIn" class="login"><form @submit.prevent="signIn"><ShieldAlert /><p class="eyebrow">SPORTLEAGUES CONTROL</p><h1>Acceso de plataforma</h1><p>Usa una cuenta con privilegio global.</p><input v-model="email" type="email" autocomplete="email" placeholder="Correo" required /><input v-model="password" type="password" autocomplete="current-password" placeholder="Contraseña" required /><button>Ingresar</button><span v-if="message">{{ message }}</span></form></section><div v-else class="layout"><aside :class="{ open: mobileOpen }"><div class="brand"><ShieldAlert /> <span>SportLeagues <small>CONTROL</small></span></div><nav><button v-for="item in menu" :key="item.key" :class="{ active: active === item.key }" @click="active = item.key; mobileOpen = false"><component :is="item.icon" />{{ item.label }}</button></nav><button class="signout" @click="signOut"><LogOut />Salir</button></aside><main><header><button class="mobile" aria-label="Abrir menú" @click="mobileOpen = !mobileOpen"><Menu /></button><div><p class="eyebrow">ENTORNO AISLADO</p><h1>{{ menu.find((item) => item.key === active)?.label }}</h1></div></header><section v-if="denied" class="state"><ShieldAlert /><h2>Acceso restringido</h2><p>Esta cuenta no tiene privilegios globales de plataforma.</p></section><section v-else-if="loading" class="state">Cargando control de plataforma…</section><template v-else><p v-if="message" class="notice">{{ message }}</p><section v-if="active === 'overview'" class="dashboard"><article v-for="card in cards" :key="card.label" class="metric"><span>{{ card.label }}</span><strong>{{ card.value.toLocaleString('es-PE') }}</strong></article><article class="wide"><h2>Estado operativo</h2><p>Las cifras se consultan en tiempo real mediante RPCs protegidas. Los cambios sensibles quedan auditados y ninguna tabla global se expone al navegador.</p></article></section><section v-else-if="active === 'tenants'" class="panel"><h2>Organizaciones</h2><div class="table"><div class="row head"><span>Nombre</span><span>Plan</span><span>Quinielas</span><span>Participantes</span></div><div v-for="tenant in tenants" :key="tenant.tenant_id" class="row"><span>{{ tenant.name }}</span><span class="pill">{{ tenant.plan_code.toUpperCase() }}</span><span>{{ tenant.pools }}</span><span>{{ tenant.participants }}</span></div></div></section><section v-else-if="active === 'requests'" class="panel"><h2>Solicitudes de plan</h2><div class="table"><div class="row head"><span>Organización</span><span>Oferta</span><span>Estado</span><span>Fecha</span></div><div v-for="request in requests" :key="request.id" class="row"><span>{{ request.tenant_name }}</span><span>{{ request.offer_code }}</span><span class="pill">{{ request.status }}</span><span>{{ new Date(request.requested_at).toLocaleDateString('es-PE') }}</span></div></div></section><section v-else class="panel"><h2>Precios y configuración</h2><article v-for="offer in offers" :key="offer.offer_code" class="offer"><strong>{{ offer.offer_code }}</strong><label>Precio menor<input v-model.number="offer.price_minor" type="number" min="0" /></label><label>Moneda<input v-model="offer.currency" maxlength="3" /></label><label>Periodo<select v-model="offer.billing_period"><option value="month">Mes</option><option value="year">Año</option><option value="one_time">Único</option></select></label><button :disabled="saving === offer.offer_code" @click="saveOffer(offer)">{{ saving === offer.offer_code ? 'Guardando…' : 'Guardar' }}</button></article></section></template></main></div></template>
